# Test: for each cell that became 1, is it on a straight unobstructed line (horizontal/vertical) passing through a unique digit, with the unique digit the nearest non-7 in that direction?
def f(g,bg):
    h,w=len(g),len(g[0])
    from collections import Counter
    cnt=Counter(v for r in g for v in r)
    bg=max(cnt,key=cnt.get)
    uniq=[(i,j) for i,r in enumerate(g) for j,v in enumerate(r) if v!=bg and cnt[v]==1]
    out=[r[:] for r in g]
    for i in range(h):
        for j in range(w):
            if g[i][j]==bg:
                for di,dj in [(0,1),(0,-1),(1,0),(-1,0)]:
                    k=1
                    while True:
                        i2,j2=i+di*k,j+dj*k
                        if not (0<=i2<h and 0<=j2<w): break
                        if (i2,j2) in set(uniq):
                            out[i][j]=1; break
                        if g[i2][j2]!=bg: break
                        k+=1
    return out
